import{f as t,o as a,c as d,a4 as o}from"./chunks/framework.6QvN0vQS.js";const m=JSON.parse('{"title":"Carátula, control de versiones y aprobaciones — GoodApps Cooperativas","description":"","frontmatter":{},"headers":[],"relativePath":"entregables-analisis-diseno/10-caratula-control-versiones.md","filePath":"entregables-analisis-diseno/10-caratula-control-versiones.md","lastUpdated":null}'),r={name:"entregables-analisis-diseno/10-caratula-control-versiones.md"};function i(n,e,c,s,l,u){return a(),d("div",null,[...e[0]||(e[0]=[o('<h1 id="caratula-control-de-versiones-y-aprobaciones-—-goodapps-cooperativas" tabindex="-1">Carátula, control de versiones y aprobaciones — GoodApps Cooperativas <a class="header-anchor" href="#caratula-control-de-versiones-y-aprobaciones-—-goodapps-cooperativas" aria-label="Permalink to &quot;Carátula, control de versiones y aprobaciones — GoodApps Cooperativas&quot;">​</a></h1><p>Artefacto 1.1 del índice de entregables (<a href="./00-INDICE"><code>00-INDICE.md</code></a>). Este documento identifica el entregable de análisis y diseño, enumera los documentos que lo componen, registra su historial y define cómo se revisa, aprueba y cambia. Deriva de la especificación vigente (<code>docs/especificacion/</code>); ante cualquier diferencia prevalece la especificación (maestra <code>00</code>, anexos y registro de decisiones <code>01</code>), según la jerarquía de la maestra §2.2.</p><hr><h2 id="_1-caratula" tabindex="-1">1. Carátula <a class="header-anchor" href="#_1-caratula" aria-label="Permalink to &quot;1. Carátula&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Campo</th><th>Valor</th></tr></thead><tbody><tr><td>Proyecto</td><td>Reemplazo de ProCoop por una plataforma SaaS para cooperativas de servicios públicos de Argentina</td></tr><tr><td>Producto</td><td><strong>GoodApps Cooperativas</strong>: plataforma SaaS multitenant, web y PWA (ERP + CRM + landing y autogestión + plataforma + cobranza y pasarelas + liquidación de impuestos + APIs; maestra §1.2)</td></tr><tr><td>Cliente</td><td><code>[Cooperativa]</code> (cooperativa piloto de los entregables: Laguna Larga, <code>LAG</code>; ver supuesto transversal del índice y DEC-088)</td></tr><tr><td>Tipo de documento</td><td>Entregable de análisis y diseño detallado (conjunto de artefactos derivados de la especificación funcional y técnica)</td></tr><tr><td>Versión del entregable</td><td>1.0</td></tr><tr><td>Fecha</td><td>05-11-2026</td></tr><tr><td>Estado</td><td>Borrador para revisión (pendiente de las aprobaciones de la sección 4)</td></tr><tr><td>Clasificación</td><td><strong>Confidencial — uso restringido al proyecto</strong> (ver sección 1.1)</td></tr><tr><td>Documento rector</td><td><code>docs/especificacion/00-ESPECIFICACION-MAESTRA.md</code> (versión 1.0, borrador consolidado)</td></tr><tr><td>Elaborado por</td><td><code>[Nombre y apellido]</code> — Analista funcional; <code>[Nombre y apellido]</code> — Arquitecto</td></tr><tr><td>Aprobado por</td><td>Ver sección 4</td></tr></tbody></table><h3 id="_1-1-clasificacion-de-confidencialidad" tabindex="-1">1.1 Clasificación de confidencialidad <a class="header-anchor" href="#_1-1-clasificacion-de-confidencialidad" aria-label="Permalink to &quot;1.1 Clasificación de confidencialidad&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Nivel</th><th>Alcance</th><th>Aplica a</th></tr></thead><tbody><tr><td>Público</td><td>Puede difundirse sin restricción</td><td>— (ningún documento del entregable)</td></tr><tr><td>Interno</td><td>Equipo del proveedor y de la cooperativa</td><td>Índice y carátula, una vez aprobados</td></tr><tr><td><strong>Confidencial</strong></td><td>Personas designadas por el proveedor y por la cooperativa; no se distribuye a terceros sin autorización escrita del patrocinador</td><td><strong>Todo el entregable en su versión 1.0</strong>: contiene arquitectura, modelo de seguridad, modelo de datos y configuraciones relevadas de la base de referencia</td></tr><tr><td>Restringido</td><td>Acceso nominal y registrado</td><td>No aplica: el entregable no contiene secretos, credenciales ni datos personales</td></tr></tbody></table><p>Reglas de manejo:</p><ul><li>El entregable <strong>no contiene datos personales reales</strong>: las personas se nombran con marcadores <code>[Nombre y apellido]</code>. De la base relevada <code>PR_LAG_DEMO</code> solo se toma configuración, nunca datos personales (DEC-088).</li><li>El entregable <strong>no contiene secretos</strong>: credenciales, claves y certificados viven en la bóveda por tenant y nunca se transcriben (DEC-074, maestra §5.1).</li><li>GoodApps actúa como prestador de servicios de tratamiento por cuenta de la cooperativa (Ley 25.326, art. 25; DEC-076); este documento no altera ese encuadre.</li></ul><hr><h2 id="_2-documentos-que-componen-el-entregable" tabindex="-1">2. Documentos que componen el entregable <a class="header-anchor" href="#_2-documentos-que-componen-el-entregable" aria-label="Permalink to &quot;2. Documentos que componen el entregable&quot;">​</a></h2><h3 id="_2-1-especificacion-vigente-fuente-normativa" tabindex="-1">2.1 Especificación vigente (fuente normativa) <a class="header-anchor" href="#_2-1-especificacion-vigente-fuente-normativa" aria-label="Permalink to &quot;2.1 Especificación vigente (fuente normativa)&quot;">​</a></h3><p>Versión y estado tomados del encabezado de cada archivo al 05-11-2026. Cuando el archivo no tiene campo de versión se indica la última actualización que consta en su contenido.</p><table tabindex="0"><thead><tr><th>Documento</th><th>Contenido</th><th>Versión</th><th>Estado declarado en el archivo</th></tr></thead><tbody><tr><td><code>00-ESPECIFICACION-MAESTRA.md</code></td><td>Documento rector: visión, decisiones, arquitectura, roles, mapa del sitio, módulos, olas, glosario general</td><td>1.0 (borrador consolidado), fecha 04-11-2026</td><td>Especificación consolidada al 04-11-2026: 31 anexos completos, cuestionario cerrado (DEC-011 a DEC-087), plan de olas, matriz y registro de huecos</td></tr><tr><td><code>01-registro-decisiones.md</code></td><td>Decisiones DEC-001 a DEC-088 con fecha, fundamento y estado</td><td>Sin campo de versión</td><td>Última decisión registrada: DEC-088 (05-11-2026), que reemplaza a DEC-081</td></tr><tr><td><code>02-preguntas-abiertas.md</code></td><td>Preguntas abiertas (PA) consolidadas con opción recomendada y estado</td><td>Sin campo de versión</td><td>Cuestionario cerrado: 516 preguntas, 93 respondidas y 423 asumidas con la recomendada (maestra §18; DEC-047, DEC-072)</td></tr><tr><td><code>03-plan-de-olas-y-prompts.md</code></td><td>Plan de construcción por olas O0–O11 y prompts para Cursor IA</td><td>1.1, fecha 05-11-2026 (reemplaza la 1.0 del 04-11-2026)</td><td>Plan consolidado</td></tr><tr><td><code>04-matriz-trazabilidad.md</code></td><td>Trazabilidad fuente → anexo/ID</td><td>1.1, fecha 05-11-2026 (reemplaza la 1.0 del 04-11-2026)</td><td>Regenerada por script; siguen abiertas las brechas de fuente de su §4 y las citas de decisiones de su §5.3</td></tr><tr><td><code>05-registro-huecos.md</code></td><td>Huecos de cobertura detectados por las fichas verticales (T12)</td><td>Sin campo de versión</td><td>Estado final 05-11-2026: 77 huecos únicos, 71 corregidos en anexo y 6 pasados a decisión; 0 abiertos</td></tr><tr><td><code>_GUIA-REDACCION-ANEXOS.md</code></td><td>Convenciones y plantilla de los anexos</td><td>Sin campo de versión</td><td>Documento de referencia (maestra §13)</td></tr></tbody></table><p>Anexos (<code>anexos/</code>). Todos declaran versión <strong>1.0</strong>.</p><table tabindex="0"><thead><tr><th>Anexo</th><th>Nombre</th><th>Estado declarado</th></tr></thead><tbody><tr><td>M01 PER</td><td>Personas, titulares, asociados, cuentas, inmuebles y domicilios</td><td>Especificación consolidada — pendiente de validar preguntas abiertas</td></tr><tr><td>M02 CAT</td><td>Catálogo de servicios, productos, planes, categorías y contrato de servicio</td><td>Ídem</td></tr><tr><td>M03 MED</td><td>Medidores, lecturas, consumos, telemedición y prepago</td><td>Ídem</td></tr><tr><td>M04 TAR</td><td>Tarifas y motor de cálculo</td><td>Ídem</td></tr><tr><td>M05 FAC</td><td>Facturación: ciclos, lotes y comprobantes</td><td>Ídem</td></tr><tr><td>M06 FIS</td><td>Fiscal e impuestos</td><td>Ídem</td></tr><tr><td>M07 COB</td><td>Cuenta corriente, cobranza, cajas, entes, débitos, pasarelas y conciliación</td><td>Ídem</td></tr><tr><td>M08 MOR</td><td>Mora, intereses, suspensión, corte, reconexión, financiación y convenios</td><td>Ídem</td></tr><tr><td>M09 CRM</td><td>CRM y atención</td><td>Ídem</td></tr><tr><td>M10 TEC</td><td>Técnica, campo, GIS/redes, obras, aprovisionamiento y telefonía</td><td>Ídem</td></tr><tr><td>M11 VEN</td><td>Ventas, presupuestos y punto de venta</td><td>Ídem</td></tr><tr><td>M12 CMP</td><td>Compras y proveedores</td><td>Ídem</td></tr><tr><td>M13 STK</td><td>Stock, equipos serializados, bienes de uso, RMA y fabricación</td><td>Ídem</td></tr><tr><td>M14 TES</td><td>Tesorería y bancos</td><td>Ídem</td></tr><tr><td>M15 CON</td><td>Contabilidad</td><td>Ídem</td></tr><tr><td>M16 SUE</td><td>Personal y sueldos</td><td>Ídem</td></tr><tr><td>M17 INS</td><td>Gestión institucional</td><td>Ídem</td></tr><tr><td>M18 SOC</td><td>Servicios sociales, otros servicios y flota</td><td>Ídem</td></tr><tr><td>M19 POR</td><td>Landing, portal y app del socio</td><td>Ídem</td></tr><tr><td>T01 PLA</td><td>Plataforma SaaS</td><td>Ídem</td></tr><tr><td>T02 IAM</td><td>Identidad, autenticación, roles, perfiles, alcance y auditoría</td><td>Ídem</td></tr><tr><td>T03 UXD</td><td>Experiencia, design system, marca, diccionario, layouts y mapa del sitio</td><td>Ídem</td></tr><tr><td>T04 CFG</td><td>Configuración versionada, parámetros, tablas maestras y geografía</td><td>Ídem</td></tr><tr><td>T04b CFG (partes 1 a 4)</td><td>Catálogo de los 1.536 parámetros de ProCoop</td><td>Ídem (las cuatro partes)</td></tr><tr><td>T05 DAT</td><td>Modelo de datos canónico consolidado</td><td>Especificación consolidada, actualizada con la fase 1 de huecos, DEC-085 a DEC-087 y el barrido final</td></tr><tr><td>T06 INT</td><td>Integraciones externas</td><td>Especificación consolidada — pendiente de validar preguntas abiertas</td></tr><tr><td>T07 MIG</td><td>Migración desde ProCoop, convivencia, corrida paralela y by-pass</td><td>Ídem</td></tr><tr><td>T08 NFR</td><td>Requisitos no funcionales, seguridad, privacidad, observabilidad y calidad</td><td>Ídem</td></tr><tr><td>T09 COM</td><td>Comunidad y comunicaciones</td><td>Ídem</td></tr><tr><td>T10 BIA</td><td>Reportes, BI, tableros, exportaciones y APIs</td><td>Ídem</td></tr><tr><td>T11 WFL</td><td>Workflow, eventos, tareas, aprobaciones y documentos</td><td>Ídem</td></tr><tr><td>T12 SRV parte 1</td><td>Fichas verticales: INT, TEL, TV, ELE, AG, CLO, GAS, ALU</td><td>Borrador para revisión funcional (control de cobertura, DEC-073), fecha 04-11-2026</td></tr><tr><td>T12 SRV parte 2</td><td>Fichas verticales: OBR, SEP, CEM, SAN, SAL, VIV, TAS, CAP, OTR</td><td>Borrador para revisión (no crea requisitos nuevos)</td></tr></tbody></table><h3 id="_2-2-documentos-de-la-carpeta-de-entregables" tabindex="-1">2.2 Documentos de la carpeta de entregables <a class="header-anchor" href="#_2-2-documentos-de-la-carpeta-de-entregables" aria-label="Permalink to &quot;2.2 Documentos de la carpeta de entregables&quot;">​</a></h3><p>Situación de la carpeta <code>docs/entregables-analisis-diseno/</code> al 05-11-2026. Los documentos en elaboración se listan sin afirmar su contenido; su descripción es la que figura en el índice.</p><table tabindex="0"><thead><tr><th>Archivo</th><th>Artefacto(s)</th><th>Estado al 05-11-2026</th></tr></thead><tbody><tr><td><code>00-INDICE.md</code></td><td>Índice de artefactos</td><td>v1.0 (05-11-2026)</td></tr><tr><td><code>01-resumen-ejecutivo-vision.md</code></td><td>1.3 Visión y alcance</td><td>v1.0 según el índice</td></tr><tr><td><code>02-arquitectura-c4.md</code></td><td>5.1, 5.2, 5.5 Arquitectura C4, contexto y despliegue</td><td>En elaboración (encabezado: 1.0, borrador para revisión)</td></tr><tr><td><code>03a-er-plataforma-personas-catalogo.md</code>, <code>03b-er-medicion-tarifas-facturacion.md</code>, <code>03c-er-cobranza-mora-crm-tecnica.md</code>, <code>03d-er-erp-administrativo.md</code></td><td>Partes A a D del 6.1 Modelo entidad-relación</td><td>En elaboración; el documento que las agrupa (<code>03-modelo-entidad-relacion.md</code>) todavía no existe en la carpeta</td></tr><tr><td><code>04-procesos-bpmn.md</code></td><td>2.1 Procesos de negocio</td><td>Previsto en el índice; no existe al momento</td></tr><tr><td><code>05-wireframes-pantallas-piloto.md</code></td><td>4.2 Wireframes</td><td>En elaboración</td></tr><tr><td><code>06-secuencias-y-estados.md</code></td><td>7.3, 7.4 Secuencias y estados</td><td>Previsto en el índice; no existe al momento</td></tr><tr><td><code>07-estrategia-pruebas.md</code></td><td>9.1, 9.4 Estrategia y plan de pruebas</td><td>En elaboración</td></tr><tr><td><code>08-plan-puesta-en-marcha.md</code></td><td>8.3, 8.4 Puesta en marcha y capacitación</td><td>En elaboración</td></tr><tr><td><code>09-riesgos-y-raci.md</code></td><td>1.4, 1.5 Interesados, RACI y riesgos</td><td>En elaboración (encabezado: 1.0, borrador para revisión)</td></tr><tr><td><code>10-caratula-control-versiones.md</code></td><td>1.1 Carátula, control de versiones y aprobaciones</td><td>Este documento, v1.0</td></tr><tr><td><code>11-glosario-negocio.md</code></td><td>1.2 Glosario de negocio unificado</td><td>v1.0 (05-11-2026)</td></tr></tbody></table><p>Los artefactos con estado &quot;Existente&quot; o &quot;Derivable&quot; en el índice se entregan por referencia a la especificación hasta que se desarrollen en esta carpeta.</p><hr><h2 id="_3-historial-de-versiones" tabindex="-1">3. Historial de versiones <a class="header-anchor" href="#_3-historial-de-versiones" aria-label="Permalink to &quot;3. Historial de versiones&quot;">​</a></h2><h3 id="_3-1-hitos-de-la-especificacion-insumo-del-entregable" tabindex="-1">3.1 Hitos de la especificación (insumo del entregable) <a class="header-anchor" href="#_3-1-hitos-de-la-especificacion-insumo-del-entregable" aria-label="Permalink to &quot;3.1 Hitos de la especificación (insumo del entregable)&quot;">​</a></h3><p>Reconstruidos a partir de la maestra (encabezado, §3, §15, §18 y §19), del registro <code>01</code>, de los encabezados de <code>03</code> y <code>04</code> y del estado final de <code>05</code>. No se registran hitos que no consten en esos documentos.</p><table tabindex="0"><thead><tr><th>Versión</th><th>Fecha</th><th>Autor</th><th>Descripción</th></tr></thead><tbody><tr><td>Decisiones rectoras</td><td>04-11-2026</td><td>Solicitante (<code>[Nombre y apellido]</code>, Patrocinador)</td><td>DEC-001 a DEC-010: stack Connectia, base única multitenant, monolito modular, Docker agnóstico, piloto Internet, olas sin fechas, todo ProCoop en alcance, muro editorial, contabilidad temprana y formato del entregable (maestra §3)</td></tr><tr><td>Cuestionario cerrado</td><td>04-11-2026</td><td>Solicitante; equipo de análisis (<code>[Nombre y apellido]</code>)</td><td>DEC-011 a DEC-087: 516 preguntas, 93 respondidas por el solicitante y 423 asumidas con la opción recomendada (DEC-047, DEC-072, DEC-087; maestra §3.1 y §18)</td></tr><tr><td>Maestra 1.0 (borrador consolidado) + anexos 1.0 + plan 1.0 + matriz 1.0</td><td>04-11-2026</td><td>Equipo de análisis y arquitectura (<code>[Nombre y apellido]</code>)</td><td>Consolidación: 31 anexos completos (M01–M19, T01–T12; T04b en 4 partes y T12 en 2), plan de olas, matriz de trazabilidad y registro de huecos (maestra, encabezado). Matriz 1.0: 2.201 unidades de fuente, 97,9 % con destino (maestra §19)</td></tr><tr><td>Procesamiento de huecos (fases 1 a 3)</td><td>05-11-2026</td><td>Equipo de análisis (<code>[Nombre y apellido]</code>)</td><td>77 huecos únicos cerrados: 71 corregidos en anexo (8 con parámetro de default propuesto que requiere validación legal) y 6 pasados a decisión; 0 abiertos (<code>05</code>, estado final). Se incorporan DEC-082 a DEC-087 a los anexos</td></tr><tr><td>Plan de olas 1.1</td><td>05-11-2026</td><td>Equipo de análisis (<code>[Nombre y apellido]</code>)</td><td>Incorpora los 83 RF nuevos de las fases 1 a 3 de huecos, DEC-082 a DEC-087 y los cambios de ola; 172 prompts (más 3 generales) que cubren 4.203 RF y 292 RNF (<code>03</code> §21; maestra §15)</td></tr><tr><td>Matriz de trazabilidad 1.1</td><td>05-11-2026</td><td>Equipo de análisis (<code>[Nombre y apellido]</code>)</td><td>Regenerada por script sobre los anexos del 05-11-2026: 1.661 unidades cubiertas directamente, 98,0 % de cobertura; 26 brechas sin cambios (<code>04</code> §20)</td></tr><tr><td>DEC-088</td><td>05-11-2026</td><td>Solicitante (<code>[Nombre y apellido]</code>, Patrocinador)</td><td>La cooperativa piloto, comercial y de migración, es Laguna Larga (<code>LAG</code>); reemplaza a DEC-081 (<code>01</code>)</td></tr></tbody></table><h3 id="_3-2-historial-del-entregable" tabindex="-1">3.2 Historial del entregable <a class="header-anchor" href="#_3-2-historial-del-entregable" aria-label="Permalink to &quot;3.2 Historial del entregable&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Versión</th><th>Fecha</th><th>Autor</th><th>Descripción</th></tr></thead><tbody><tr><td>1.0</td><td>05-11-2026</td><td><code>[Nombre y apellido]</code> — Analista funcional; <code>[Nombre y apellido]</code> — Arquitecto</td><td>Primera emisión del entregable de análisis y diseño sobre la especificación al 05-11-2026: índice, carátula, glosario y los documentos de la sección 2.2. Borrador para revisión</td></tr></tbody></table><hr><h2 id="_4-roles-de-elaboracion-revision-y-aprobacion" tabindex="-1">4. Roles de elaboración, revisión y aprobación <a class="header-anchor" href="#_4-roles-de-elaboracion-revision-y-aprobacion" aria-label="Permalink to &quot;4. Roles de elaboración, revisión y aprobación&quot;">​</a></h2><p>Los nombres se completan al circular el entregable. La firma puede ser manuscrita sobre la versión impresa o firma electrónica con OTP según la política de firma del proyecto (DEC-078 aplica al producto; su uso para este entregable lo decide el patrocinador).</p><table tabindex="0"><thead><tr><th>Rol</th><th>Responsabilidad sobre el entregable</th><th>Nombre y apellido</th><th>Organización</th><th>Firma</th><th>Fecha</th></tr></thead><tbody><tr><td>Analista funcional</td><td>Elabora los artefactos funcionales (glosario, procesos, wireframes, casos de uso) y mantiene la trazabilidad con la especificación</td><td><code>[Nombre y apellido]</code></td><td><code>[Proveedor]</code></td><td></td><td></td></tr><tr><td>Arquitecto</td><td>Elabora los artefactos de arquitectura, datos, integración y no funcionales; revisa la coherencia técnica</td><td><code>[Nombre y apellido]</code></td><td><code>[Proveedor]</code></td><td></td><td></td></tr><tr><td>Referente de la cooperativa</td><td>Revisa que procesos, vocabulario y configuraciones reflejen la operación de la cooperativa piloto; canaliza las preguntas dirigidas a ella (DEC-088)</td><td><code>[Nombre y apellido]</code></td><td><code>[Cooperativa]</code></td><td></td><td></td></tr><tr><td>Contador</td><td>Revisa los artefactos con efecto contable, fiscal y de capital social (M05, M06, M07, M15, M17); valida los parámetros con default propuesto de encuadre fiscal (<code>05</code>, HUECO-CAP-04)</td><td><code>[Nombre y apellido]</code></td><td><code>[Cooperativa]</code></td><td></td><td></td></tr><tr><td>Asesor legal</td><td>Revisa privacidad, plazos de prescripción, firma y parámetros que requieren validación legal antes de producción (DEC-052, DEC-076, <code>05</code>)</td><td><code>[Nombre y apellido]</code></td><td><code>[Cooperativa]</code></td><td></td><td></td></tr><tr><td>Patrocinador</td><td>Aprueba el entregable, resuelve controversias de alcance y autoriza los cambios que afectan decisiones rectoras</td><td><code>[Nombre y apellido]</code></td><td><code>[Cooperativa]</code></td><td></td><td></td></tr></tbody></table><p>Circuito de aprobación de una versión:</p><ol><li><strong>Elaboración</strong>: Analista funcional y Arquitecto, cada uno sobre sus artefactos.</li><li><strong>Revisión cruzada</strong>: el Arquitecto revisa los artefactos funcionales y el Analista los técnicos.</li><li><strong>Revisión de la cooperativa</strong>: Referente (operación), Contador (contable y fiscal) y Asesor legal (normativo), cada uno sobre los artefactos de su competencia.</li><li><strong>Aprobación</strong>: Patrocinador, una vez cerradas o aceptadas las observaciones.</li></ol><hr><h2 id="_5-procedimiento-de-control-de-cambios-del-entregable" tabindex="-1">5. Procedimiento de control de cambios del entregable <a class="header-anchor" href="#_5-procedimiento-de-control-de-cambios-del-entregable" aria-label="Permalink to &quot;5. Procedimiento de control de cambios del entregable&quot;">​</a></h2><h3 id="_5-1-que-se-considera-un-cambio" tabindex="-1">5.1 Qué se considera un cambio <a class="header-anchor" href="#_5-1-que-se-considera-un-cambio" aria-label="Permalink to &quot;5.1 Qué se considera un cambio&quot;">​</a></h3><ul><li><strong>Corrección editorial</strong>: redacción, formato, enlaces o numeración, sin efecto sobre el contenido.</li><li><strong>Corrección de derivación</strong>: el entregable no refleja fielmente la especificación. Se corrige el entregable, porque la especificación prevalece.</li><li><strong>Cambio de contenido</strong>: se modifica una regla, un alcance, un dato o un criterio. Siempre nace en la especificación y luego se propaga al entregable.</li></ul><h3 id="_5-2-como-se-pide-un-cambio" tabindex="-1">5.2 Cómo se pide un cambio <a class="header-anchor" href="#_5-2-como-se-pide-un-cambio" aria-label="Permalink to &quot;5.2 Cómo se pide un cambio&quot;">​</a></h3><p>Toda solicitud se registra con un identificador <code>SC-ENT-NNN</code> (convención propuesta por este documento) y los siguientes datos:</p><table tabindex="0"><thead><tr><th>Campo</th><th>Contenido</th></tr></thead><tbody><tr><td>Solicitante y rol</td><td><code>[Nombre y apellido]</code>, rol de la sección 4</td></tr><tr><td>Artefacto y sección afectados</td><td>Número del índice (por ejemplo, 2.1) y sección</td></tr><tr><td>Descripción</td><td>Qué debe cambiar y por qué</td></tr><tr><td>Fuente</td><td>Sección de la maestra, anexo e ID (RF, RN, PAN, DEC, PA, HUE) que respalda o contradice el cambio</td></tr><tr><td>Tipo</td><td>Editorial / derivación / contenido</td></tr><tr><td>Impacto</td><td>Artefactos, anexos y olas afectados</td></tr></tbody></table><h3 id="_5-3-tratamiento-segun-el-tipo" tabindex="-1">5.3 Tratamiento según el tipo <a class="header-anchor" href="#_5-3-tratamiento-segun-el-tipo" aria-label="Permalink to &quot;5.3 Tratamiento según el tipo&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Tipo</th><th>Tratamiento</th><th>Registro en la especificación</th></tr></thead><tbody><tr><td>Editorial</td><td>El autor del artefacto corrige y sube la versión menor del documento</td><td>Ninguno</td></tr><tr><td>Derivación</td><td>El autor corrige contra la fuente citada; el revisor del rol que detectó la diferencia verifica</td><td>Ninguno</td></tr><tr><td>Contenido que <strong>cambia una decisión</strong></td><td>Se registra una nueva decisión en <code>01-registro-decisiones.md</code> (DEC-089 en adelante). La decisión anterior no se borra: se marca <code>Reemplazada por DEC-xxx</code></td><td><code>01</code></td></tr><tr><td>Contenido que <strong>requiere definir algo</strong></td><td>Se registra como pregunta en <code>02-preguntas-abiertas.md</code>. Mientras no se responde rige la opción recomendada y los requisitos quedan <code>A validar</code> (DEC-047, DEC-072; maestra §16, punto 5). Al responderse genera una DEC</td><td><code>02</code>, luego <code>01</code></td></tr><tr><td>Contenido que revela un <strong>faltante o una contradicción entre anexos</strong></td><td>Se registra en <code>05-registro-huecos.md</code> con propuesta, anexo responsable y gravedad; se corrige en el anexo responsable o pasa a PA si requiere decisión</td><td><code>05</code></td></tr></tbody></table><p>Después de aplicar un cambio de contenido en la especificación:</p><ol><li>Se actualiza el anexo dueño del dato (maestra §12 y T05) y, si corresponde, la maestra.</li><li>Se regenera la matriz de trazabilidad con el procedimiento de su §14 cuando el cambio es importante (maestra §19).</li><li>Si el cambio mueve requisitos de ola, se actualiza el plan de olas y su sección de cambios.</li><li>Se actualizan los artefactos del entregable afectados y se sube su versión (sección 6).</li><li>Se registra en el historial (sección 3.2) qué versión del entregable incorpora cada <code>SC-ENT</code>.</li></ol><h3 id="_5-4-reglas" tabindex="-1">5.4 Reglas <a class="header-anchor" href="#_5-4-reglas" aria-label="Permalink to &quot;5.4 Reglas&quot;">​</a></h3><ul><li>El entregable nunca introduce reglas que no estén en la especificación; si falta algo, se registra como PA (maestra §16, punto 6).</li><li>El texto reemplazado se conserva como referencia (&quot;Texto anterior&quot; o &quot;Reemplazado&quot;), igual que en la especificación, para no perder trazabilidad.</li><li>Un cambio que afecta una decisión rectora (DEC-001 a DEC-010) o el alcance requiere aprobación del Patrocinador antes de aplicarse.</li><li>Los parámetros resueltos con un default propuesto que requiere validación legal (<code>05</code>, estado final) no se dan por aprobados hasta la firma del Asesor legal.</li></ul><hr><h2 id="_6-convenciones-de-numeracion-de-versiones" tabindex="-1">6. Convenciones de numeración de versiones <a class="header-anchor" href="#_6-convenciones-de-numeracion-de-versiones" aria-label="Permalink to &quot;6. Convenciones de numeración de versiones&quot;">​</a></h2><p>Se adopta el esquema <code>MAYOR.MENOR</code>, coherente con la especificación (<code>03</code> y <code>04</code> pasaron de 1.0 a 1.1 conservando una sección de cambios y el texto reemplazado).</p><table tabindex="0"><thead><tr><th>Cambio</th><th>Efecto en la versión</th><th>Ejemplo</th></tr></thead><tbody><tr><td>Primera emisión consolidada</td><td>1.0</td><td>Este entregable al 05-11-2026</td></tr><tr><td>Correcciones editoriales o de derivación, o incorporación de cambios de contenido que no alteran decisiones ni alcance</td><td>Sube la menor</td><td>1.0 → 1.1</td></tr><tr><td>Cambio de alcance, de una decisión rectora o reemisión completa tras una nueva consolidación de la especificación</td><td>Sube la mayor y la menor vuelve a 0</td><td>1.3 → 2.0</td></tr></tbody></table><p>Reglas complementarias:</p><ul><li>Cada documento lleva su propia versión en el encabezado; la versión del entregable (carátula) sube cuando cambia al menos uno de sus documentos.</li><li>El <strong>estado</strong> se informa aparte de la versión: <code>En elaboración</code> → <code>Borrador para revisión</code> → <code>Aprobado</code> → <code>Reemplazado por x.y</code>. La aprobación no cambia el número de versión; cualquier modificación posterior sí.</li><li>Toda versión distinta de 1.0 incluye una sección &quot;Cambios de la versión x.y&quot; con lo modificado y el valor reemplazado, como <code>03</code> §21 y <code>04</code> §20.</li><li>Las fechas se escriben <code>dd-mm-aaaa</code> (maestra §13).</li><li>Los identificadores de la especificación (DEC, PA, RF, RN, CTR, HUE y demás) son estables y no se renumeran; un ID reemplazado se marca y no se reutiliza (<code>01</code>, encabezado).</li></ul><hr><h2 id="_7-fuentes" tabindex="-1">7. Fuentes <a class="header-anchor" href="#_7-fuentes" aria-label="Permalink to &quot;7. Fuentes&quot;">​</a></h2><ul><li>Maestra <code>00</code>: encabezado, §1.4, §2.2, §3, §3.1, §12, §13, §15, §16, §18, §19.</li><li><code>01-registro-decisiones.md</code>: DEC-047, DEC-052, DEC-072, DEC-074, DEC-076, DEC-078, DEC-081, DEC-088.</li><li><code>02-preguntas-abiertas.md</code> (encabezado y política vigente), <code>03-plan-de-olas-y-prompts.md</code> (encabezado y §21), <code>04-matriz-trazabilidad.md</code> (encabezado y §20), <code>05-registro-huecos.md</code> (estado final).</li><li>Encabezados de los anexos M01–M19 y T01–T12.</li><li><a href="./00-INDICE"><code>00-INDICE.md</code></a> de esta carpeta.</li></ul>',55)])])}const b=t(r,[["render",i]]);export{m as __pageData,b as default};
